export const SOFT_PROFANITY_LIST = [
  "걸레",
  "대걸레",
];

const norm = (s) => String(s || "").toLowerCase();

const EXCLUDE_SET = new Set([
  ...NEUTRAL_TERMS.map(norm),
  ...ALLOW_TERMS.map(norm),
  ...SOFT_PROFANITY_LIST.map(norm),
]);

